import{_ as a,o as i,c as s,a2 as e}from"./chunks/framework.1lR7qgqY.js";const k=JSON.parse('{"title":"第 19 章 版本鎖定與升級流程","description":"","frontmatter":{},"headers":[],"relativePath":"ops/19-versioning.md","filePath":"ops/19-versioning.md","lastUpdated":1793002104000}'),d={name:"ops/19-versioning.md"};function l(o,t,n,r,h,p){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-19-章-版本鎖定與升級流程" tabindex="-1">第 19 章 版本鎖定與升級流程 <a class="header-anchor" href="#第-19-章-版本鎖定與升級流程" aria-label="Permalink to &quot;第 19 章 版本鎖定與升級流程&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (指令未實機驗證)</li><li>資料基準日: 2026-10-26</li><li>待查證: 容器映像摘要值的查詢指令為 Docker 通用做法, 未實機驗證; 各應用程式是否支援資料庫降版, 須逐一查證</li></ul></div><p><strong>結論</strong>: 鎖定版本不等於不升級. 做法是「固定在已知版本, 有公告或需求時, 先備份, 先在測試環境驗證, 再升級, 並保留回退的路」. 這樣能避開 2026 年已出現的浮動標籤事件, 又不會因久未更新而累積漏洞 (信心: 中高, 屬推論).</p><h2 id="_19-1-版本記錄與固定方式" tabindex="-1">19.1 版本記錄與固定方式 <a class="header-anchor" href="#_19-1-版本記錄與固定方式" aria-label="Permalink to &quot;19.1 版本記錄與固定方式&quot;">​</a></h2><h3 id="為什麼不用浮動標籤" tabindex="-1">為什麼不用浮動標籤 <a class="header-anchor" href="#為什麼不用浮動標籤" aria-label="Permalink to &quot;為什麼不用浮動標籤&quot;">​</a></h3><p>2026-10-21 的 LiteLLM 事件中, <code>latest</code>, <code>main-latest</code>, <code>main-stable</code> 等標籤都曾指向惡意映像 (來源: LiteLLM 官方事故報告, 見<a href="/docs-handbook-poc/deploy/10-gateway">第 10.3 節</a>). 浮動標籤隨時可能指向不同內容, 不能當作版本固定.</p><h3 id="固定方式" tabindex="-1">固定方式 <a class="header-anchor" href="#固定方式" aria-label="Permalink to &quot;固定方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對象</th><th>固定方式</th></tr></thead><tbody><tr><td>容器映像</td><td>使用明確的版本標籤; 較嚴格者連同摘要值 (digest) 一起固定</td></tr><tr><td>Ollama (Linux)</td><td>安裝腳本加上 <code>OLLAMA_VERSION</code> 環境變數, 如 <code>curl -fsSL https://ollama.com/install.sh | OLLAMA_VERSION=&lt;版本&gt; sh</code> (來源: Ollama 文件 Linux); 版本號從 GitHub releases 頁取得</td></tr><tr><td>Python 套件</td><td>在需求檔中寫明確版本, 例如 <code>litellm==&lt;版本&gt;</code></td></tr><tr><td>模型檔</td><td>記錄來源庫與 revision (見<a href="/docs-handbook-poc/deploy/08-first-run">第 8.5 節</a>)</td></tr></tbody></table><p>查詢本機映像的摘要值 (Docker 通用指令, 未實機驗證):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --digests</span></span></code></pre></div><h3 id="版本紀錄表" tabindex="-1">版本紀錄表 <a class="header-anchor" href="#版本紀錄表" aria-label="Permalink to &quot;版本紀錄表&quot;">​</a></h3><p>每個元件一列, 每次變動都更新. 這張表同時是還原與稽核時的依據.</p><table tabindex="0"><thead><tr><th>元件</th><th>版本或摘要值</th><th>安裝或升級日期</th><th>來源</th><th>上一版</th><th>備註</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_19-2-升級流程" tabindex="-1">19.2 升級流程 <a class="header-anchor" href="#_19-2-升級流程" aria-label="Permalink to &quot;19.2 升級流程&quot;">​</a></h2><p>建議順序 (信心: 中高, 屬推論):</p><ol><li><strong>決定要不要升</strong>: 讀發行說明與安全公告 (<a href="/docs-handbook-poc/ops/20-advisories-incidents">第 20 章</a>). 漏洞已有利用紀錄時列為優先; 純功能更新可以排到下個維護時段.</li><li><strong>備份</strong>: 依<a href="/docs-handbook-poc/ops/18-backup">第 18 章</a>備份資料卷, 並確認備份可用.</li><li><strong>在隔離環境先試</strong>: 用另一組容器名稱與連接埠, 載入備份的資料, 先升級試跑.</li><li><strong>跑測試集</strong>: 用<a href="/docs-handbook-poc/apply/14-evaluation">第 14 章</a>的回歸測試集比較升級前後的結果與耗時.</li><li><strong>正式升級</strong>: 以相同的啟動指令與環境變數重建容器; 密鑰類設定要沿用. 例如 Open WebUI 的 <code>WEBUI_SECRET_KEY</code> 若改變, 重建後所有人須重新登入 (來源: Open WebUI Quick Start).</li><li><strong>更新版本紀錄</strong>: 填寫 19.1 的紀錄表.</li><li><strong>觀察</strong>: 升級後一週內留意日誌 (<a href="/docs-handbook-poc/deploy/08-first-run">第 8.7 節</a>) 與使用者回報.</li></ol><p><strong>以 Open WebUI 為例</strong> (來源: Open WebUI Quick Start; 該文件的範例使用浮動標籤 <code>:main</code>, 本手冊建議改用固定版本):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ghcr.io/open-webui/open-webui:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">新版本標</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">籤</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 以先前相同的 docker run 指令重新啟動, 並沿用同一個 WEBUI_SECRET_KEY</span></span></code></pre></div><h3 id="緊急修補" tabindex="-1">緊急修補 <a class="header-anchor" href="#緊急修補" aria-label="Permalink to &quot;緊急修補&quot;">​</a></h3><p>漏洞已有利用紀錄時, 時間比完整驗證重要. 縮短流程但不跳過備份: 備份 → 升級 → 跑核心測試題 → 視結果擴大. 若暫時無法修補, 先降低暴露面: 關閉對外連線, 停用受影響功能, 或暫停服務.</p><h2 id="_19-3-回退" tabindex="-1">19.3 回退 <a class="header-anchor" href="#_19-3-回退" aria-label="Permalink to &quot;19.3 回退&quot;">​</a></h2><p>回退要事先準備, 事發後才準備會來不及.</p><table tabindex="0"><thead><tr><th>對象</th><th>回退做法</th></tr></thead><tbody><tr><td>容器映像</td><td>保留上一版映像與啟動指令, 以上一版標籤重新啟動</td></tr><tr><td>資料卷</td><td>部分應用程式升級時會轉換資料庫結構, 回退舊版可能無法讀取新結構 (推論, 信心: 中高), 因此升級前的備份是回退的依據</td></tr><tr><td>Ollama</td><td>以 <code>OLLAMA_VERSION</code> 重新安裝指定的舊版 (Linux)</td></tr><tr><td>模型</td><td>升級模型時保留舊模型, 確認新模型的測試結果後再移除</td></tr></tbody></table><p>回退流程: 停止服務 → 以上一版重新啟動 → 若新版已轉換資料結構, 舊版無法讀取, 還原升級前的備份 → 跑核心測試題確認 → 記錄原因.</p><h2 id="_19-4-何時該縮減元件" tabindex="-1">19.4 何時該縮減元件 <a class="header-anchor" href="#_19-4-何時該縮減元件" aria-label="Permalink to &quot;19.4 何時該縮減元件&quot;">​</a></h2><ul><li>無法每週檢查安全公告時, 移除非必要元件.</li><li>以<a href="/docs-handbook-poc/intro/03-layers">第 3 章分層圖</a>檢視哪些層可以拿掉, 優先拿掉 ○ 與 ◇ 層中用量最低的.</li><li>元件的儲存庫已封存, 或長期沒有更新, 且沒有替代維護者時, 規劃替換 (例: 版本頁記載 LLM Guard 的儲存庫已於 2026-07-09 封存).</li></ul>`,26)])])}const b=a(d,[["render",l]]);export{k as __pageData,b as default};
